    // hexdumpWords prints a word-oriented hex dump of [p, p+len).
    //
    // If mark != nil, it will be passed to hexdumper.mark.
    void hexdumpWords(uintptr_t p, uintptr_t len, std::function<void (uintptr_t _1, hexdumpMarker _2)> mark)
    {
        printlock();

        // Provide a default annotation
        auto symMark = [=](uintptr_t u, hexdumpMarker hm) mutable -> void
        {
            if(mark != nullptr)
            {
                mark(u, hm);
            }

            // Can we symbolize this value?
            auto val = *(uintptr_t*)(gocpp::unsafe_pointer(u));
            auto fn = findfunc(val);
            if(rec::valid(gocpp::recv(fn)))
            {
                rec::start(gocpp::recv(hm));
                print("<"_s, funcname(fn), "+"_s, hex(val - rec::entry(gocpp::recv(fn))), ">\n"_s);
            }
        };

        auto h = gocpp::Init<hexdumper>([=](auto& x) {
            x.addr = p;
            x.mark = symMark;
        });
        rec::write(gocpp::recv(h), unsafe::Slice((unsigned char*)(gocpp::unsafe_pointer(p)), len));
        rec::close(gocpp::recv(h));
        printunlock();
    }

